// A chain the loopback server sends and the client's own root for it, made
// once with openssl and frozen here: a P-256 root "nish loopback CA"
// (CA:TRUE, keyCertSign) and two leaves it issued for the same key as
// `leafPrivate`, each with SAN DNS:localhost and IP:127.0.0.1, serverAuth
// and digitalSignature. The good leaf runs from 2026-01-01 to 2049-12-31;
// the expired one ran through 2024. `net_tls_common`'s own leaf stays as it
// is: it is self-signed and carried in recorded transcripts.
import { TLS_SIGNATURE_ECDSA_SECP256R1_SHA256 } from "nish/net/tls/codec";
import { TlsServerConfig } from "nish/net/tls";
import { fromHex } from "../crypto_x509/hex";

/** The root: the one certificate the client's trust holds. */
export const loopbackRoot = (): u8[] =>
  fromHex(
    "",
  );

/** A leaf for localhost and 127.0.0.1 under the root, valid until 2049. */
export const goodLeaf = (): u8[] =>
  fromHex(
    "",
  );

/** The same leaf, but valid only through 2024. */
export const expiredLeaf = (): u8[] =>
  fromHex(
    "",
  );

/** A server configuration sending `chain`, offering `alpn`, signing with the leaf key. */
export const chainConfig = (chain: u8[][], alpn: string[]): TlsServerConfig => {
  const none: u8[] = [];
  return {
    certificateChain: chain,
    alpn: alpn,
    quicTransportParameters: none,
    extraExtensions: none,
    signatureScheme: TLS_SIGNATURE_ECDSA_SECP256R1_SHA256,
    quic: false,
  };
};
